CREATE TABLE P_LEW_MART_MSI.T_AGG_NET_INT_MTH_DET_1 CLUSTER BY (CY_MONTH) COMMENT = 'Table contains the base data for the Report Nettoleistung 1104004.112. Data is provided by store and partial week.'
(
  CY_MONTH                        NUMBER(38,0)                  COMMENT 'Monat_1 des Geschäftsjahres im Format "JJJJMM"'
, CY_MONTH_NAME                   VARCHAR(57) COLLATE 'en-ci'   COMMENT 'Monatsname des Geschäftsjahres'
, CY_WEEK                         NUMBER(38,0)                  COMMENT 'Geschäftsjahr - Woche_1 Id - Format "JJJJMM"'
, CY_PARTIAL_WEEK                 NUMBER(38,0)                  COMMENT 'Geschäftsjahr - Teilwoche Id - 1 = erster Teil / 2 = zweiter Teil der Woche_1'
, CY_PARTIAL_WEEK_NAME            VARCHAR(27) COLLATE 'en-ci'   COMMENT 'Geschäftsjahr - Woche_1/Teilwoche - Name der Woche_1 - Format = JJJJ KW 99 plus "/1" für den ersten Teil oder "/2" für den zweiten Teil der Woche_1'
, CLIENT_ID                       NUMBER(38,0)                  COMMENT 'Landeskennzeichen'
, ASPECT_DESC                     VARCHAR(4) COLLATE 'en-ci'    COMMENT 'Gesellschaftsform Bezeichnung'
, WH_DESC                         VARCHAR(50) COLLATE 'en-ci'   COMMENT 'Gesellschaftsbezeichnung'
, ASPECT_ID                       NUMBER(38,0)                  COMMENT 'Gesellschaftsform (1 = Betriebs- 2 = Vertriebsgesellschaft)'
, SALES_MANAGER_ID                NUMBER(38,0)                  COMMENT 'Bezirksleiter-Nr.'
, WH_ID                           NUMBER(38,0)                  COMMENT 'Gesellschaftsnummer'
, WH_ID_EXP                       NUMBER(38,0)                  COMMENT 'Gesellschafts-Nr.-exp'
, SALES_MANAGER_NAME              VARCHAR(50) COLLATE 'en-ci'   COMMENT 'Bezirksleiter-Name'
, ACCOUNT_MANAGER_ID              NUMBER(38,0)                  COMMENT 'Vertriebsleiter-Nr.'
, ACCOUNT_MANAGER_NAME            VARCHAR(50) COLLATE 'en-ci'   COMMENT 'Vertriebsleiter-Name'
, MOVE_TO_STORE_ID                NUMBER(38,0)                  COMMENT 'Filial-Nr. nach letztem Filialumzug'
, MOVE_STORE_DESC                 VARCHAR(255) COLLATE 'en-ci'  COMMENT 'Filialname nach letztem Filialumzug'
, ORIG_STORE_NR                   NUMBER(38,0)                  COMMENT 'Original Filial-Nr.'
, CURR_TOT_ID                     NUMBER(38,0)                  COMMENT 'Fixe Werte für EUR=0, GBP=40 sonst Client_Id'
, CURRENCY_ISO_CD                 VARCHAR(3) COLLATE 'en-ci'    COMMENT 'Iso-Code Währung'
, COUNTRY_GROUP_ID                NUMBER(38,0)                  COMMENT 'Landesgruppe Kennzeichen'
, COUNTRY_GROUP_DESC              VARCHAR(60) COLLATE 'en-ci'   COMMENT 'Landesgruppe Bezeichnung'
, COUNTRY_DESC                    VARCHAR(35) COLLATE 'en-ci'   COMMENT 'Filial-Land_1 Bezeichnung'
, GL_REGION_ID                    NUMBER(38,0)                  COMMENT 'Geschäftsleitungsregion ID'
, GL_REGION_DESC                  VARCHAR(60) COLLATE 'en-ci'   COMMENT 'Beschreibung Geschäftsleitungsregion'
, VAL_RETAIL                      NUMBER(38,5)                  COMMENT 'Umsatz (gross value)'
, VAL_RETAIL_NET                  NUMBER(38,5)                  COMMENT 'Umsatz (net value)'
, VAL_RETAIL_CUM                  NUMBER(38,5)                  COMMENT 'Umsatz aufgelaufen im Geschäftsjahr (gross value)'
, VAL_RETAIL_NET_CUM              NUMBER(38,5)                  COMMENT 'Umsatz aufgelaufen im Geschäftsjahr (net value)'
, WT_HRS_NET_PY_CUM               NUMBER(38,5)                  COMMENT 'Arbeitsstunden effektiv aufgelaufen im Geschäftsjahr, Vorjahr'
, MT_HRS_PY_CUM                   NUMBER(38,5)                  COMMENT 'Schulungsstunden aufgelaufen im Geschäftsjahr, voriges Geschäftsjahr'
, NET_HRS_STORE_PLAN              NUMBER(38,5)                  COMMENT 'effektive Arbeitsstunden geplant'
, VAL_RETAIL_WT_HRS_NET           NUMBER(38,5)                  COMMENT 'Umsatz an Tagen mit effektiven Arbeitsstunden (gross value)'
, VAL_RTL_NET_WT_HRS_NET          NUMBER(38,5)                  COMMENT 'Umsatz an Tagen mit effektiven Arbeitsstunden (net value)'
, MT_HRS_CUM                      NUMBER(38,5)                  COMMENT 'Schulungsstunden aufgelaufen im Geschäftsjahr'
, MT_HRS_PY                       NUMBER(38,5)                  COMMENT 'Schulungsstunden, Vorjahr'
, NET_HRS_STORE_PLAN_CUM          NUMBER(38,5)                  COMMENT 'effektive Arbeitsstunden geplant aufgelaufen im Geschäftsjahr'
, VAL_RETAIL_PLAN_CUM             NUMBER(38,5)                  COMMENT 'Umsatz aufgelaufen im Geschäftsjahr geplant (gross value)'
, VAL_RETAIL_PLAN_NET_CUM         NUMBER(38,5)                  COMMENT 'Umsatz aufgelaufen im Geschäftsjahr geplant (net value)'
, WT_HRS_NET                      NUMBER(38,5)                  COMMENT 'Arbeitsstunden effektiv'
, MT_HRS                          NUMBER(38,5)                  COMMENT 'Schulungsstunden'
, VAL_RETAIL_WT_HRS_NET_PY_CUM    NUMBER(38,5)                  COMMENT 'Umsatz an Tagen mit effektiven Arbeitsstunden aufgelaufen im Geschäftsjahr (gross value), Vorjahr'
, VAL_RTL_NET_WT_HRS_NET_PY_CUM   NUMBER(38,5)                  COMMENT 'Umsatz an Tagen mit effektiven Arbeitsstunden aufgelaufen im Geschäftsjahr (net value), Vorjahr'
, WT_HRS_NET_PY                   NUMBER(38,5)                  COMMENT 'Arbeitsstunden effektiv, Vorjahr'
, VAL_RETAIL_WT_HRS_NET_PY        NUMBER(38,5)                  COMMENT 'Umsatz an Tagen mit effektiven Arbeitsstunden (gross value), Vorjahr'
, VAL_RTL_NET_WT_HRS_NET_PY       NUMBER(38,5)                  COMMENT 'Umsatz an Tagen mit effektiven Arbeitsstunden (net value), Vorjahr'
, WT_HRS_NET_CUM                  NUMBER(38,5)                  COMMENT 'Arbeitsstunden effektiv aufgelaufen im Geschäftsjahr'
, VAL_RETAIL_PLAN                 NUMBER(38,5)                  COMMENT 'Umsatz geplant (gross value)'
, VAL_RETAIL_PLAN_NET             NUMBER(38,5)                  COMMENT 'Umsatz geplant (net value)'
, VAL_RETAIL_WT_HRS_NET_CUM       NUMBER(38,5)                  COMMENT 'Umsatz an Tagen mit effektiven Arbeitsstunden aufgelaufen im Geschäftsjahr (gross value)'
, VAL_RTL_NET_WT_HRS_NET_CUM      NUMBER(38,5)                  COMMENT 'Umsatz an Tagen mit effektiven Arbeitsstunden aufgelaufen im Geschäftsjahr (net value)'
, SALES_PIECES_PLAN               NUMBER(38,5)                  COMMENT 'Abverkaufwert Plan'
, SALES_PIECES_PLAN_CUM           NUMBER(38,5)                  COMMENT 'Abverkaufwert Plan akkumuliert'
)
;